const fs=require('node:fs');
(async()=>{const event=JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH));const pr=event.pull_request.number;await new Promise(r=>setTimeout(r,20000));const headers={Authorization:'Bearer '+process.env.GITHUB_TOKEN,'User-Agent':'TDV2-950-QA',Accept:'application/vnd.github+json'};const get=async p=>{const r=await fetch('https://api.github.com/repos/'+process.env.GITHUB_REPOSITORY+p,{headers});if(!r.ok)throw Error('Read '+r.status);return r.json()};const comments=await get('/issues/'+pr+'/comments'),pull=await get('/pulls/'+pr),checks=await get('/commits/'+event.pull_request.head.sha+'/check-runs');fs.mkdirSync('snapshots',{recursive:true});fs.writeFileSync('snapshots/'+process.argv[2]+'.json',JSON.stringify({comments,pull,checks},null,2));})().catch(e=>{console.error(e.message);process.exitCode=1});
